j:jelly.g:evaluate:
  var styleSheet = GlidePropertiesDB.get('password_reset.stylesheet', 'css_pwd_reset_default');
  if(!styleSheet){
	styleSheet = 'css_pwd_reset_default';
  }

  var css = new GlideRecord('content_css');
  css.addQuery('name', styleSheet);
  css.query();
  css.next();
  var cssId = css.getUniqueValue();
